// allows for svg imports
declare module "*.svg" {
  const content: any;
  export default content;
}

// allows for png imports
declare module "*.png" {
  const content: any;
  export default content;
}

// allows for jpg imports
declare module "*.jpg" {
  const content: any;
  export default content;
}

// allows for jpeg imports
declare module "*.jpeg" {
  const content: any;
  export default content;
}
